import * as THREE from "three";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import type { CityMap } from "@afterfall/world";
import { CellKind } from "@afterfall/world";

/** The kit shipped in `public/art/props`, generated by `tools/blender/props.py`. */
export const PROP_KINDS = ["car", "dumpster", "fence", "sign", "lamp", "barrier"] as const;
export type PropKind = (typeof PROP_KINDS)[number];

export interface PropPlacement {
  x: number;
  z: number;
  /** Yaw in radians, so a car sits along the street instead of across it. */
  rot: number;
  scale: number;
}

const MAX_PER_KIND = 70;

/** Deterministic hash, so the same seed always dresses the same city. */
function hash(a: number, b: number, seed: number): number {
  let h = a * 374761393 + b * 668265263 + seed * 2147483647;
  h = (h ^ (h >>> 13)) * 1274126177;
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Which prop belongs on a given side of the street. */
function pickKind(r: number): PropKind {
  if (r < 0.34) return "car";
  if (r < 0.52) return "barrier";
  if (r < 0.66) return "dumpster";
  if (r < 0.8) return "lamp";
  if (r < 0.92) return "sign";
  return "fence";
}

/**
 * Dresses the sidewalks: walks the perimeter of every block and drops a prop
 * every few metres where the navigation grid is free. Nothing is placed on a
 * road cell, inside a building or on a door.
 */
export function placeProps(
  city: CityMap,
  grid: { kind: Int8Array | Uint8Array; cellOf(x: number, y: number): number; cell: number },
  seed = 1,
): Map<PropKind, PropPlacement[]> {
  const out = new Map<PropKind, PropPlacement[]>();
  const pitch = city.blockSize + city.roadWidth;
  const inset = 1.1;
  const step = 7.5;

  for (let bj = 0; bj < city.blocksY; bj++) {
    for (let bi = 0; bi < city.blocksX; bi++) {
      const x0 = city.roadWidth + bi * pitch + inset;
      const z0 = city.roadWidth + bj * pitch + inset;
      const x1 = x0 + city.blockSize - inset * 2;
      const z1 = z0 + city.blockSize - inset * 2;
      const sides: [number, number, number, number, number][] = [
        // x0, z0, dx, dz, rot: the prop faces the street it borders.
        [x0, z0, 1, 0, 0],
        [x1, z0, 0, 1, Math.PI / 2],
        [x1, z1, -1, 0, Math.PI],
        [x0, z1, 0, -1, -Math.PI / 2],
      ];
      for (const [sx, sz, dx, dz, rot] of sides) {
        const len = Math.abs(dx) ? x1 - x0 : z1 - z0;
        for (let t = 2; t < len - 2; t += step) {
          const wobble = hash(bi * 31 + t, bj * 17 + t, seed) * 3;
          const x = sx + dx * (t + wobble) + dz * 0.4;
          const z = sz + dz * (t + wobble) + dx * 0.4;
          const cell = grid.cellOf(x, z);
          if (grid.kind[cell] !== CellKind.Free) continue;
          const r = hash(bi * 7 + t, bj * 13 + t, seed + 5);
          if (r > 0.42) continue; // leave the street breathing: density, not clutter
          const kind = pickKind(hash(bi * 3 + t, bj * 11 + t, seed + 9));
          const list = out.get(kind) ?? [];
          if (list.length >= MAX_PER_KIND) continue;
          list.push({
            x,
            z,
            rot: rot + (hash(bi + t, bj + t, seed + 11) - 0.5) * 0.5,
            scale: 0.9 + hash(bi + t, bj + t, seed + 13) * 0.25,
          });
          out.set(kind, list);
        }
      }
    }
  }
  return out;
}

export interface PropScene {
  /** Meshes added to the scene, so they can be dropped when the city changes. */
  meshes: THREE.Object3D[];
  instances: number;
  drawCalls: number;
}

/**
 * Loads the kit and instances it. Every child mesh of a GLB becomes its own
 * InstancedMesh, which keeps the multi-material props (a car has body, glass
 * and tyres) at one draw call each without merging materials.
 */
export async function loadProps(
  baseUrl: string,
  placements: Map<PropKind, PropPlacement[]>,
  onReady: (scene: PropScene) => void,
): Promise<void> {
  const loader = new GLTFLoader();
  const meshes: THREE.Object3D[] = [];
  let instances = 0;
  let drawCalls = 0;
  const matrix = new THREE.Matrix4();
  const quat = new THREE.Quaternion();
  const pos = new THREE.Vector3();
  const scale = new THREE.Vector3();

  await Promise.all(
    PROP_KINDS.map(async (kind) => {
      const list = placements.get(kind);
      if (!list || list.length === 0) return;
      let gltf;
      try {
        gltf = await loader.loadAsync(`${baseUrl}art/props/${kind}.glb`);
      } catch {
        return; // a missing prop must never take the scene down
      }
      gltf.scene.updateMatrixWorld(true);
      gltf.scene.traverse((child) => {
        if (!(child instanceof THREE.Mesh)) return;
        const geo = child.geometry.clone();
        geo.applyMatrix4(child.matrixWorld);
        const src = child.material as THREE.MeshStandardMaterial;
        const mat = new THREE.MeshStandardMaterial({
          color: src.color ? src.color.clone() : new THREE.Color(0x888888),
          roughness: src.roughness ?? 0.85,
          metalness: src.metalness ?? 0,
          flatShading: true,
        });
        const inst = new THREE.InstancedMesh(geo, mat, list.length);
        // Shadows on props are the expensive half in software rendering; the
        // kit is small and mostly hugged by the building shadows anyway.
        inst.castShadow = kind === "car" || kind === "barrier" || kind === "dumpster";
        inst.receiveShadow = true;
        inst.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        list.forEach((p, i) => {
          pos.set(p.x, 0, p.z);
          quat.setFromAxisAngle(new THREE.Vector3(0, 1, 0), p.rot);
          scale.setScalar(p.scale);
          matrix.compose(pos, quat, scale);
          inst.setMatrixAt(i, matrix);
        });
        inst.instanceMatrix.needsUpdate = true;
        inst.computeBoundingSphere();
        meshes.push(inst);
        instances += list.length;
        drawCalls += 1;
      });
    }),
  );

  onReady({ meshes, instances, drawCalls });
}
